const updateShareRule = `-- name: UpdateShareRule :execrows
UPDATE staff_share_rules
SET basis = $1, rate = $2, fixed_amount = $3,
    valid_from = $4, note = $5
WHERE organization_id = $6 AND id = $7
`

type UpdateShareRuleParams struct {
	Basis          string         `json:"basis"`
	Rate           pgtype.Numeric `json:"rate"`
	FixedAmount    pgtype.Numeric `json:"fixed_amount"`
	ValidFrom      pgtype.Date    `json:"valid_from"`
	Note           string         `json:"note"`
	OrganizationID int64          `json:"organization_id"`
	ID             int64          `json:"id"`
}

func (q *Queries) UpdateShareRule(ctx context.Context, arg UpdateShareRuleParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateShareRule,
		arg.Basis,
		arg.Rate,
		arg.FixedAmount,
		arg.ValidFrom,
		arg.Note,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
